1	"use client";
2	
3	import {
4	  useCallback,
5	  useEffect,
6	  useRef,
7	  useState,
8	  useTransition,
9	  type ClipboardEvent,
10	} from "react";
11	import {
12	  listConversations,
13	  replyToConversation,
14	  replyWithAttachment,
15	  closeConversation,
16	  assignConversation,
17	  signalAgentTyping,
18	} from "@/lib/actions-chat";
19	
20	/**
21	 * Admin live-chat inbox. Two-pane layout: a conversation list (unread + newest
22	 * first) and a thread view with a reply box. Polls `listConversations` every
23	 * few seconds so new visitor messages appear without a manual refresh.
24	 */
25	
26	type Attachment = { id: string; mime: string; sizeBytes: number };
27	type Msg = {
28	  id: string;
29	  sender: string;
30	  body: string;
31	  createdAt: string;
32	  attachment?: Attachment | null;
33	};
34	type Convo = {
35	  id: string;
36	  visitorId: string;
37	  userId: string | null;
38	  name: string | null;
39	  email: string | null;
40	  status: string;
41	  assignedToId: string | null;
42	  unreadForAgent: boolean;
43	  lastMessageAt: string;
44	  createdAt: string;
45	  visitorTyping: boolean;
46	  messages: Msg[];
47	};
48	
49	/** Three-dot "typing…" pulse, matching the widget's indicator. */
50	function TypingDots() {
51	  return (
52	    <span className="flex items-center gap-1" aria-hidden="true">
53	      {[0, 150, 300].map((delay) => (
54	        <span
55	          key={delay}
56	          className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-300"
57	          style={{ animationDelay: `${delay}ms`, animationDuration: "1s" }}
58	        />
59	      ))}
60	    </span>
61	  );
62	}
63	
64	const POLL_MS = 5000;
65	
66	// Client-side pre-checks only; replyWithAttachment re-validates by signature.
67	const ACCEPT_IMAGES = "image/png,image/jpeg,image/gif,image/webp";
68	const ALLOWED_IMAGE_TYPES = new Set(["image/png", "image/jpeg", "image/gif", "image/webp"]);
69	const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
70	
71	function imageError(file: File): string | null {
72	  if (!ALLOWED_IMAGE_TYPES.has(file.type)) return "Only PNG, JPEG, GIF, or WEBP images.";
73	  if (file.size > MAX_IMAGE_BYTES) return "Image must be 5 MB or smaller.";
74	  return null;
75	}
76	
77	function timeAgo(iso: string): string {
78	  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
79	  if (s < 60) return `${s}s ago`;
80	  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
81	  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
82	  return `${Math.floor(s / 86400)}d ago`;
83	}
84	
85	export default function ChatInbox({ initial }: { initial: Convo[] }) {
86	  const [convos, setConvos] = useState<Convo[]>(initial);
87	  const [selectedId, setSelectedId] = useState<string | null>(initial[0]?.id ?? null);
88	  const [draft, setDraft] = useState("");
89	  const [error, setError] = useState("");
90	  const [pendingImage, setPendingImage] = useState<{ file: File; url: string } | null>(null);
91	  const [pending, start] = useTransition();
92	  const scrollRef = useRef<HTMLDivElement>(null);
93	  const fileInputRef = useRef<HTMLInputElement>(null);
94	  const lastTypingPingRef = useRef(0); // throttle "agent is typing" pings
95	
96	  useEffect(() => {
97	    return () => {
98	      if (pendingImage) URL.revokeObjectURL(pendingImage.url);
99	    };
100	  }, [pendingImage]);
101	
102	  function pickImage(file: File | null | undefined) {
103	    if (!file) return;
104	    const err = imageError(file);
105	    if (err) {
106	      setError(err);
107	      return;
108	    }
109	    setError("");
110	    setPendingImage((prev) => {
111	      if (prev) URL.revokeObjectURL(prev.url);
112	      return { file, url: URL.createObjectURL(file) };
113	    });
114	  }
115	
116	  function clearImage() {
117	    setPendingImage((prev) => {
118	      if (prev) URL.revokeObjectURL(prev.url);
119	      return null;
120	    });
121	    if (fileInputRef.current) fileInputRef.current.value = "";
122	  }
123	
124	  function onPaste(e: ClipboardEvent) {
125	    const item = Array.from(e.clipboardData?.items ?? []).find((i) =>
126	      i.type.startsWith("image/")
127	    );
128	    if (item) {
129	      const file = item.getAsFile();
130	      if (file) {
131	        e.preventDefault();
132	        pickImage(file);
133	      }
134	    }
135	  }
136	
137	  const refresh = useCallback(async () => {
138	    try {
139	      const rows = await listConversations();
140	      setConvos(rows);
141	    } catch {
142	      /* transient — next poll retries */
143	    }
144	  }, []);
145	
146	  useEffect(() => {
147	    const t = setInterval(refresh, POLL_MS);
148	    return () => clearInterval(t);
149	  }, [refresh]);
150	
151	  const selected = convos.find((c) => c.id === selectedId) ?? null;
152	
153	  // Tell the visitor's widget this agent is composing, throttled to ~once/2.5s.
154	  function pingTyping() {
155	    if (!selectedId) return;
156	    const now = Date.now();
157	    if (now - lastTypingPingRef.current < 2500) return;
158	    lastTypingPingRef.current = now;
159	    void signalAgentTyping(selectedId);
160	  }
161	
162	  useEffect(() => {
163	    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
164	  }, [selected?.messages.length, selectedId]);
165	
166	  function doReply() {
167	    if (!selected || pending) return;
168	    if (!draft.trim() && !pendingImage) return;
169	    const body = draft;
170	    setError("");
171	
172	    if (pendingImage) {
173	      const fd = new FormData();
174	      fd.append("conversationId", selected.id);
175	      fd.append("file", pendingImage.file);
176	      if (body.trim()) fd.append("body", body.trim());
177	      start(async () => {
178	        const res = await replyWithAttachment(fd);
179	        if (res.error) {
180	          setError(res.error);
181	          return;
182	        }
183	        setDraft("");
184	        clearImage();
185	        await refresh();
186	      });
187	      return;
188	    }
189	
190	    start(async () => {
191	      const res = await replyToConversation(selected.id, body);
192	      if (res.error) {
193	        setError(res.error);
194	        return;
195	      }
196	      setDraft("");
197	      await refresh();
198	    });
199	  }
200	
201	  function doClose() {
202	    if (!selected) return;
203	    start(async () => {
204	      await closeConversation(selected.id);
205	      await refresh();
206	    });
207	  }
208	
209	  function doAssign() {
210	    if (!selected) return;
211	    start(async () => {
212	      await assignConversation(selected.id);
213	      await refresh();
214	    });
215	  }
216	
217	  function label(c: Convo): string {
218	    return c.name || c.email || `Visitor ${c.visitorId.slice(0, 8)}`;
219	  }
220	
221	  return (
222	    <div className="grid gap-4 lg:grid-cols-[20rem_1fr]">
223	      {/* Conversation list */}
224	      <div className="card max-h-[70vh] space-y-1 overflow-y-auto p-2">
225	        {convos.length === 0 && (
226	          <p className="p-4 text-center text-sm text-slate-500">No conversations yet.</p>
227	        )}
228	        {convos.map((c) => {
229	          const last = c.messages[c.messages.length - 1];
230	          const active = c.id === selectedId;
231	          return (
232	            <button
233	              key={c.id}
234	              onClick={() => setSelectedId(c.id)}
235	              className={`w-full rounded-xl border px-3 py-2.5 text-left transition ${
236	                active
237	                  ? "border-brand-500/50 bg-brand-500/10"
238	                  : "border-transparent hover:bg-white/[0.04]"
239	              }`}
240	            >
241	              <div className="flex items-center justify-between gap-2">
242	                <span className="truncate text-sm font-medium text-slate-100">
243	                  {label(c)}
244	                </span>
245	                <div className="flex shrink-0 items-center gap-1.5">
246	                  {c.unreadForAgent && (
247	                    <span className="h-2 w-2 rounded-full bg-amber-400" />
248	                  )}
249	                  {c.status === "CLOSED" && (
250	                    <span className="text-[10px] uppercase text-slate-500">closed</span>
251	                  )}
252	                </div>
253	              </div>
254	              <div className="mt-0.5 flex items-center justify-between gap-2">
255	                <span className="truncate text-xs text-slate-400">
256	                  {last ? (last.sender === "agent" ? "You: " : "") + last.body : "…"}
257	                </span>
258	                <span className="shrink-0 text-[10px] text-slate-500">
259	                  {timeAgo(c.lastMessageAt)}
260	                </span>
261	              </div>
262	            </button>
263	          );
264	        })}
265	      </div>
266	
267	      {/* Thread view */}
268	      <div className="card flex max-h-[70vh] flex-col p-0">
269	        {!selected ? (
270	          <div className="flex flex-1 items-center justify-center p-10 text-sm text-slate-500">
271	            Select a conversation to view it.
272	          </div>
273	        ) : (
274	          <>
275	            <div className="flex flex-wrap items-center justify-between gap-2 border-b border-white/10 px-4 py-3">
276	              <div>
277	                <p className="text-sm font-semibold text-slate-100">{label(selected)}</p>
278	                <p className="text-xs text-slate-400">
279	                  {selected.email || "no email"}
280	                  {selected.userId ? " · registered customer" : " · guest"} ·{" "}
281	                  {selected.status.toLowerCase()}
282	                </p>
283	              </div>
284	              <div className="flex items-center gap-2">
285	                <button
286	                  className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
287	                  onClick={doAssign}
288	                  disabled={pending}
289	                >
290	                  Assign to me
291	                </button>
292	                {selected.status !== "CLOSED" && (
293	                  <button
294	                    className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
295	                    onClick={doClose}
296	                    disabled={pending}
297	                  >
298	                    Close
299	                  </button>
300	                )}
301	              </div>
302	            </div>
303	
304	            <div ref={scrollRef} className="flex-1 space-y-3 overflow-y-auto px-4 py-4">
305	              {selected.messages.map((m) => (
306	                <div
307	                  key={m.id}
308	                  className={`flex ${m.sender === "agent" ? "justify-end" : "justify-start"}`}
309	                >
310	                  <div
311	                    className={`max-w-[75%] space-y-1.5 whitespace-pre-wrap rounded-2xl px-3.5 py-2 text-sm ${
312	                      m.sender === "agent"
313	                        ? "bg-brand-500 text-white"
314	                        : "border border-white/10 bg-white/[0.06] text-slate-200"
315	                    }`}
316	                  >
317	                    {m.attachment && (
318	                      <a
319	                        href={`/api/chat/attachment/${m.attachment.id}`}
320	                        target="_blank"
321	                        rel="noopener noreferrer"
322	                        className="block"
323	                      >
324	                        {/* eslint-disable-next-line @next/next/no-img-element */}
325	                        <img
326	                          src={`/api/chat/attachment/${m.attachment.id}`}
327	                          alt="attachment"
328	                          className="max-h-48 max-w-full rounded-lg border border-white/10 object-contain"
329	                        />
330	                      </a>
331	                    )}
332	                    {m.body && <div>{m.body}</div>}
333	                    <div
334	                      className={`mt-1 text-[10px] ${
335	                        m.sender === "agent" ? "text-white/60" : "text-slate-500"
336	                      }`}
337	                    >
338	                      {timeAgo(m.createdAt)}
339	                    </div>
340	                  </div>
341	                </div>
342	              ))}
343	              {selected.visitorTyping && (
344	                <div className="flex justify-start" aria-live="polite">
345	                  <div className="flex items-center gap-2 rounded-2xl border border-white/10 bg-white/[0.06] px-3.5 py-2.5">
346	                    <TypingDots />
347	                    <span className="text-[11px] text-slate-400">{label(selected)} is typing…</span>
348	                  </div>
349	                </div>
350	              )}
351	            </div>
352	
353	            <div className="border-t border-white/10 px-4 py-3">
354	              {error && <p className="mb-2 text-xs text-red-400">{error}</p>}
355	              {pendingImage && (
356	                <div className="mb-2 flex items-center gap-2">
357	                  <div className="relative">
358	                    {/* eslint-disable-next-line @next/next/no-img-element */}
359	                    <img
360	                      src={pendingImage.url}
361	                      alt="preview"
362	                      className="h-14 w-14 rounded-lg border border-white/10 object-cover"
363	                    />
364	                    <button
365	                      type="button"
366	                      aria-label="Remove image"
367	                      onClick={clearImage}
368	                      className="absolute -right-1.5 -top-1.5 flex h-5 w-5 items-center justify-center rounded-full bg-slate-800 text-slate-200 ring-1 ring-white/20 hover:bg-slate-700"
369	                    >
370	                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
371	                        <path d="M18 6 6 18M6 6l12 12" />
372	                      </svg>
373	                    </button>
374	                  </div>
375	                  <span className="truncate text-xs text-slate-400">{pendingImage.file.name}</span>
376	                </div>
377	              )}
378	              <input
379	                ref={fileInputRef}
380	                type="file"
381	                accept={ACCEPT_IMAGES}
382	                className="hidden"
383	                onChange={(e) => pickImage(e.target.files?.[0])}
384	              />
385	              <div className="flex items-end gap-2">
386	                <button
387	                  type="button"
388	                  aria-label="Attach image"
389	                  onClick={() => fileInputRef.current?.click()}
390	                  disabled={pending}
391	                  className="shrink-0 rounded-lg p-2 text-slate-400 hover:bg-white/10 hover:text-slate-200 disabled:opacity-50"
392	                >
393	                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
394	                    <path d="M21.44 11.05 12.25 20.24a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48" />
395	                  </svg>
396	                </button>
397	                <textarea
398	                  className="input min-h-[2.5rem] flex-1 resize-none py-2 text-sm"
399	                  placeholder="Type your reply…"
400	                  value={draft}
401	                  maxLength={5000}
402	                  rows={1}
403	                  onChange={(e) => {
404	                    setDraft(e.target.value);
405	                    if (e.target.value.trim()) pingTyping();
406	                  }}
407	                  onPaste={onPaste}
408	                  onKeyDown={(e) => {
409	                    if (e.key === "Enter" && !e.shiftKey) {
410	                      e.preventDefault();
411	                      doReply();
412	                    }
413	                  }}
414	                  disabled={pending}
415	                />
416	                <button
417	                  className="btn-primary shrink-0 px-4 py-2 text-sm"
418	                  onClick={doReply}
419	                  disabled={pending || (!draft.trim() && !pendingImage)}
420	                >
421	                  {pending ? "…" : "Reply"}
422	                </button>
423	              </div>
424	            </div>
425	          </>
426	        )}
427	      </div>
428	    </div>
429	  );
430	}
