prisma/schema.prisma:1970:model ChatMessage {
=== ChatMessage block ===
model ChatMessage {
  id             String           @id @default(cuid())
  conversationId String
  conversation   ChatConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  sender         String // "visitor" | "agent"
  body           String // may be "" for an image-only message
  // Rich UI attached to a bot message (Kodee-style plan cards etc.) — a JSON
  // array of PlanCard, resolved server-side from real catalog data so the model
  // only ever picks card keys. Null for plain messages.
  cardsJson      String?
  createdAt      DateTime         @default(now())
  attachment     ChatAttachment?

  @@index([conversationId, createdAt])
}
=== ChatConversation block ===
model ChatConversation {
  id             String        @id @default(cuid())
  userId         String? // set if the visitor is a signed-in customer
  visitorId      String // anonymous client id (cookie/localStorage)
  name           String?
  email          String?
  status         String        @default("OPEN") // OPEN | CLOSED
  assignedToId   String? // staff user id handling it
  unreadForAgent Boolean       @default(true)
  unreadForUser  Boolean       @default(false)
  lastMessageAt  DateTime      @default(now())
  createdAt      DateTime      @default(now())
  // AI-assistant human-handoff window: set (atomically) when the bot escalates
  // to a live agent and emails them. While set, the bot stays quiet waiting for
  // a human; if the window elapses with no agent, the bot posts the "no agents
  // available" fallback and clears this back to null (so a later ask can retry).
  botEscalatedAt DateTime?
  messages       ChatMessage[]

  @@index([status, lastMessageAt])
  @@index([visitorId])
}

1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { realUser } from "./auth";
7	import { requireArea } from "./rbac";
8	import { validateImageBytes } from "./chat-attachment";
9	import { checkRateLimit } from "./rate-limit";
10	import { markTyping, readTyping } from "./chat-typing";
11	
12	/**
13	 * Staff-side live-chat actions. Every export gates on `requireArea("support")`
14	 * so only support staff / admins can read or write conversations. This file is
15	 * a "use server" module, so it may export **async functions only**.
16	 */
17	
18	/** Shape returned to the admin inbox client component. */
19	type InboxAttachment = { id: string; mime: string; sizeBytes: number } | null;
20	type InboxMessage = {
21	  id: string;
22	  sender: string;
23	  body: string;
24	  createdAt: string;
25	  attachment: InboxAttachment;
26	};
27	type InboxConversation = {
28	  id: string;
29	  visitorId: string;
30	  userId: string | null;
31	  name: string | null;
32	  email: string | null;
33	  status: string;
34	  assignedToId: string | null;
35	  unreadForAgent: boolean;
36	  lastMessageAt: string;
37	  createdAt: string;
38	  /** True while the visitor is composing (transient, self-expiring). */
39	  visitorTyping: boolean;
40	  messages: InboxMessage[];
41	};
42	
43	/** List conversations for the inbox, unread + newest first. Polled by the client. */
44	export async function listConversations(): Promise<InboxConversation[]> {
45	  await requireArea("support");
46	  const rows = await db.chatConversation.findMany({
47	    orderBy: [{ unreadForAgent: "desc" }, { lastMessageAt: "desc" }],
48	    take: 200,
49	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
50	  });
51	  return rows.map((c) => ({
52	    id: c.id,
53	    visitorId: c.visitorId,
54	    userId: c.userId,
55	    name: c.name,
56	    email: c.email,
57	    status: c.status,
58	    assignedToId: c.assignedToId,
59	    unreadForAgent: c.unreadForAgent,
60	    lastMessageAt: c.lastMessageAt.toISOString(),
61	    createdAt: c.createdAt.toISOString(),
62	    visitorTyping: readTyping(c.id).visitor,
63	    messages: c.messages.map((m) => ({
64	      id: m.id,
65	      sender: m.sender,
66	      body: m.body,
67	      createdAt: m.createdAt.toISOString(),
68	      attachment: m.attachment
69	        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
70	        : null,
71	    })),
72	  }));
73	}
74	
75	/** Fetch a single conversation's messages (used when opening / polling a thread). */
76	export async function getConversation(id: string): Promise<InboxConversation | null> {
77	  await requireArea("support");
78	  if (typeof id !== "string" || !id) return null;
79	  const c = await db.chatConversation.findUnique({
80	    where: { id },
81	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
82	  });
83	  if (!c) return null;
84	  return {
85	    id: c.id,
86	    visitorId: c.visitorId,
87	    userId: c.userId,
88	    name: c.name,
89	    email: c.email,
90	    status: c.status,
91	    assignedToId: c.assignedToId,
92	    unreadForAgent: c.unreadForAgent,
93	    lastMessageAt: c.lastMessageAt.toISOString(),
94	    createdAt: c.createdAt.toISOString(),
95	    visitorTyping: readTyping(c.id).visitor,
96	    messages: c.messages.map((m) => ({
97	      id: m.id,
98	      sender: m.sender,
99	      body: m.body,
100	      createdAt: m.createdAt.toISOString(),
101	      attachment: m.attachment
102	        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
103	        : null,
104	    })),
105	  };
106	}
107	
108	/**
109	 * Staff reply: append an "agent" message, flag the thread unread for the user,
110	 * clear the agent-unread flag, and assign it to the replying staff member.
111	 */
112	export async function replyToConversation(
113	  id: string,
114	  body: string
115	): Promise<{ error?: string; ok?: boolean }> {
116	  const staff = await requireArea("support");
117	
118	  const parsed = z
119	    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
120	    .safeParse({ id, body });
121	  if (!parsed.success) return { error: "Message must be between 1 and 5000 characters." };
122	
123	  const convo = await db.chatConversation.findUnique({ where: { id: parsed.data.id } });
124	  if (!convo) return { error: "Conversation not found." };
125	
126	  await db.$transaction([
127	    db.chatMessage.create({
128	      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
129	    }),
130	    db.chatConversation.update({
131	      where: { id: parsed.data.id },
132	      data: {
133	        status: "OPEN",
134	        unreadForUser: true,
135	        unreadForAgent: false,
136	        assignedToId: staff.id,
137	        lastMessageAt: new Date(),
138	      },
139	    }),
140	  ]);
141	
142	  // If the visitor is a signed-in customer, drop them a notification.
143	  if (convo.userId) {
144	    await db.notification
